#include <stdio.h>
#include <string.h>
#include <stdbool.h>

// Simple wildcard matcher supporting '*' (any sequence, including empty)
// and '?' (any single character). Implements the same logic as the
// original obfuscated program (prog26_wildcard_match).
static bool wildcard_match(const char *pat, const char *txt)
{
    size_t p_len = strlen(pat);
    size_t t_len = strlen(txt);
    // DP table: dp[i][j] = true if pat[0..i-1] matches txt[0..j-1]
    // We allocate (p_len+1) * (t_len+1) booleans.
    bool *dp = (bool *)calloc((p_len + 1) * (t_len + 1), sizeof(bool));
    if (!dp) return false; // allocation failure, treat as no match
    #define DP(i,j) dp[(i)*(t_len+1) + (j)]
    DP(0,0) = true;
    // Initialize first row (pattern empty) – only matches empty text.
    for (size_t j = 1; j <= t_len; ++j) DP(0,j) = false;
    // Fill DP table.
    for (size_t i = 1; i <= p_len; ++i) {
        char pc = pat[i-1];
        for (size_t j = 0; j <= t_len; ++j) {
            if (pc == '*') {
                // '*' matches empty sequence (dp[i-1][j]) or any char (dp[i][j-1])
                DP(i,j) = DP(i-1,j) || (j>0 && DP(i,j-1));
            } else if (pc == '?') {
                DP(i,j) = (j>0 && DP(i-1,j-1));
            } else {
                DP(i,j) = (j>0 && DP(i-1,j-1) && pc == txt[j-1]);
            }
        }
    }
    bool result = DP(p_len, t_len);
    free(dp);
    return result;
    #undef DP
}

int main(int argc, char *argv[])
{
    if (argc != 3) {
        puts("USAGE");
        return 0;
    }
    const char *pattern = argv[1];
    const char *text = argv[2];
    if (strlen(pattern) >= 65) { // original program allowed up to 64 characters
        puts("USAGE");
        return 0;
    }
    bool match = wildcard_match(pattern, text);
    puts(match ? "MATCH" : "NO_MATCH");
    return 0;
}
